// fill: four arcs round a non-planar loop: (0, 0, 0), (20, 0, 5), (20, 20, 0), (0, 20, 5), each bowed 2 mm up on an upright plane
export function c008(context is Context, id is Id)
{
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(e1, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(10, 4.5) * millimeter, "end" : vector(20, 5) * millimeter });
    skSolve(e1);
    const e2 = newSketchOnPlane(context, id + "e2", { "sketchPlane" : plane(vector(20, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skArc(e2, "a1", { "start" : vector(0, 5) * millimeter, "mid" : vector(10, 4.5) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(e2);
    const e3 = newSketchOnPlane(context, id + "e3", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(e3, "a1", { "start" : vector(20, 0) * millimeter, "mid" : vector(10, 4.5) * millimeter, "end" : vector(0, 5) * millimeter });
    skSolve(e3);
    const e4 = newSketchOnPlane(context, id + "e4", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skArc(e4, "a1", { "start" : vector(20, 5) * millimeter, "mid" : vector(10, 4.5) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(e4);
    fill(context, id + "fill1", { "edges" : [{ "entities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "e1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e3", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e4", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]), "continuity" : GeometricContinuity.G0 }], "surfaceOperationType" : NewSurfaceOperationType.NEW });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "fill1", EntityType.BODY), BodyType.SHEET)) };
}

// boundary-surface: the arcs of batch 062 c001 and arcs bowed 3 mm down joining their ends
